add{ id=260, name="The Slave Pens", isRaid=false, minLevel=61, mapID=547, loreFDID=608238, bgFDID=608160, buttonFDID=608199, desc="Coilfang Reservoir is the name for a naga-dominated compound that lurks under Zangarmarsh's deepest waters. The reservoir, punctured throughout by massive open pipes and pistons, seems big enough to house armies - and, yet, its purpose isn't strictly military.",
  encounters = {
    { id=570, name="Mennu the Betrayer", order=1, desc="Mennu is one of the Broken, draenei twisted and deformed by demonic energies unleashed by the orcs. When the naga invaded Zangarmarsh, many of these tragic beings desperately attempted to escape the region. Mennu, however, chose a different path to freedom. In exchange for his own life, he betrayed his fellow Broken to the serpentine invaders and agreed to lord over his kin as a slave driver.", uiMapID=265, x=0.49043700099, y=0.27049198747, rootSection=5902,
