add{ id=262, name="The Underbog", isRaid=false, minLevel=62, mapID=546, loreFDID=608238, bgFDID=608160, buttonFDID=608199, desc="Coilfang Reservoir is the name for a naga-dominated compound that lurks under Zangarmarsh's deepest waters. The reservoir, punctured throughout by massive open pipes and pistons, seems big enough to house armies - and, yet, its purpose isn't strictly military.",
  encounters = {
    { id=576, name="Hungarfen", order=1, desc="Unlike his ally, Quagmirran, the great fungal giant Hungarfen has thus far eluded enslavement by the naga. Nonetheless, he remains aggressive to all outsiders who tread into the deepest caverns of Zangarmarsh. Oblivious to the naga's machinations in other parts of the region, Hungarfen spends much of his time tending the Underspore, an ancient plant said to be his most prized possession.", uiMapID=262, x=0.69398897886, y=0.89959001541, rootSection=6006,
