add{ id=258, name="The Mechanar", isRaid=false, minLevel=68, mapID=554, loreFDID=608257, bgFDID=608179, buttonFDID=608218, desc="The mighty Tempest Keep was created by the enigmatic naaru: sentient beings of pure energy and the sworn enemies of the Burning Legion. In addition to serving as a base of operations for the naaru, the structure itself possesses the technology to teleport through alternate dimensions, traveling from one location to another in the blink of an eye.",
