add{ id=249, name="Magisters' Terrace", isRaid=false, minLevel=69, mapID=585, loreFDID=608247, bgFDID=608169, buttonFDID=608208, desc="After his defeat in Tempest Keep, Kael'thas Sunstrider publicly revealed his alliance with the ruthless Burning Legion. Intent upon summoning the demon lord Kil'jaeden, Kael'thas has returned to the Isle of Quel'Danas to make the final preparations for his master's arrival.",
  encounters = {
    { id=530, name="Selin Fireheart", order=1, desc="Once a respected captain of Kael'Thas Sunstrider's personal guard, Selin Fireheart has maintained an unswervingly fierce loyalty to his lord while losing his sanity. Selin has been seduced by the demonic energies of the crystals which surround his chamber, and cannot stop from reveling in their vile power. He will slay any who dare approach the Magisters' Terrace and will drink the magic, life, and blood from their dead bodies.", uiMapID=349, x=0.42486399412, y=0.22336100042, rootSection=5078,
      creatures = { {display=22642, file=607767, name="Selin Fireheart"} },
