add{ id=253, name="Shadow Labyrinth", isRaid=false, minLevel=69, mapID=555, loreFDID=608232, bgFDID=608154, buttonFDID=608193, desc="The original exiles on Draenor found death to be an unsettling and unfortunate consequence of life, and so the draenei hid their dead away in the subterranean grave-city of Auchindoun, a labyrinthine marvel located beneath the forests of Terokkar.",
  encounters = {
    { id=544, name="Ambassador Hellmaw", order=1, desc="A powerful demonic servant and acolyte of pain, Ambassador Hellmaw is dedicated to the art of death. He loves nothing more than the taste of a mortal's lifeblood tinged with horror and despair.  Hellmaw is bound by the fel orcs of the Shadow Labyrinth and fed a constant stream of prisoners, bolstering the demon to serve the black will of his masters.", uiMapID=260, x=0.21857899427, y=0.39549198747, rootSection=5261,
      creatures = { {display=18821, file=607536, name="Ambassador Hellmaw"} },
      loot = {
        {id=29434,pct=100.0,diff="h"}, {id=27884,pct=16.7}, {id=27885,pct=16.7}, {id=27886,pct=16.7}, {id=27887,pct=16.7}, {id=27888,pct=16.7}, {id=27889,pct=16.7}, {id=30559,pct=5.0,diff="h"}, {id=30560,pct=5.0,diff="h"}, {id=30563,pct=5.0,diff="h"},
