          body="Blackheart the Inciter incites chaos in the minds of all players, causing them to randomly attack each other for 30 seconds." },
        { id=5264, title="War Stomp", parent=0, child=0, sib=5265, order=2, spell=0, icon=132091, flags=0, cdisp=0,
          body="Blackheart the Inciter stomps, inflicting Physical damage to all players within $33707A1 yards, knocking them back." },
