        { id=5269, title="Void Traveler", parent=0, child=5270, sib=0, order=4, spell=0, icon=0, flags=0, cdisp=17081,
          body="When Grandmaster Vorpil enters combat he summons 5 Void Rifts which summon Void Travelers throughout the fight." },
        { id=5270, title="Shadow Nova", parent=5269, child=0, sib=5271, order=5, spell=0, icon=136201, flags=32, cdisp=0,
          body="When a Void Traveler reaches Grandmaster Vorpil, it explodes inflicting Shadow damage to all players within $33846A1 yards." },
        { id=5271, title="Empowering Shadows", parent=5269, child=0, sib=0, order=6, spell=0, icon=136221, flags=0, cdisp=0,
          body="When a Void Traveler explodes from Shadow Nova, it heals Grandmaster Vorpil and increases his Shadow damage done for $33783d." },
      },
    },
    { id=547, name="Murmur", order=4, desc="\"In the beginning\"... \"So far away\"... such phrases cannot begin to describe this elemental's origin. Its existence heralds pure destruction. Worlds shatter and the pieces scatter at its whim. Only the truly mad would think to summon it. Perhaps there is yet time to banish Murmur before it fully enters Outland.", uiMapID=260, x=0.80874300003, y=0.39139300585, rootSection=5272,
      creatures = { {display=18839, file=607720, name="Murmur"} },
