        {id=30560,pct=10.0,diff="h"}, {id=30563,pct=10.0,diff="h"}, {id=24309,pct=5.0},
      },
      sections = {
        { id=5272, title="Sonic Boom", parent=0, child=0, sib=5273, order=1, spell=0, icon=136010, flags=0, cdisp=0,
          body="Murmur releases a massive burst of sonic energy that blasts players within $33666A1 yards with Nature damage, then inflicts additional Nature damage every $33666t2 seconds for $33666d.  While affected by Sonic Boom, movement speed is reduced by $33666s3%." },
        { id=5273, title="Magnetic Pull", parent=0, child=0, sib=5274, order=2, spell=0, icon=136039, flags=0, cdisp=0,
          body="Murmur pulls all players towards him.", diff="n" },
        { id=5274, title="Murmur's Touch", parent=0, child=0, sib=5275, order=3, spell=0, icon=136114, flags=0, cdisp=0,
          body="Murmur touches a player, causing the air around them to pulse with sonic energy for $33711d. When Murmur's Touch fades, a shockwave of energy inflicts $33686s2 Nature damage and silences all players within $33686A1 yards of the player that was touched for $33686d.", diff="n" },
