add{ id=254, name="The Arcatraz", isRaid=false, minLevel=69, mapID=552, loreFDID=608257, bgFDID=608179, buttonFDID=608218, desc="The mighty Tempest Keep was created by the enigmatic naaru: sentient beings of pure energy and the sworn enemies of the Burning Legion. In addition to serving as a base of operations for the naaru, the structure itself possesses the technology to teleport through alternate dimensions, traveling from one location to another in the blink of an eye.",
  encounters = {
    { id=548, name="Zereketh the Unbound", order=1, desc="Most creatures from the Twisting Nether require constant directions from their masters, but a select few voidwraiths need no such orders. Zereketh stands at the entrance to Arcatraz, ready to slay all who would dare challenge him.", uiMapID=269, x=0.59289598465, y=0.24385300279, rootSection=5279,
