add{ id=259, name="The Shattered Halls", isRaid=false, minLevel=69, mapID=540, loreFDID=608246, bgFDID=608168, buttonFDID=608207, desc="At the heart of Outland's barren Hellfire Peninsula stands Hellfire Citadel, a nearly impenetrable bastion that served as the Horde's base of operations throughout the First and Second Wars.",
  encounters = {
    { id=566, name="Grand Warlock Nethekurse", order=1, desc="Nethekurse, once a shaman of the Shadowmoon clan, abandoned his reverence for the elements to master the art of wielding fel magic. The demonic energies at his command have left him a husk who finds delight only in torturing young fel orcs to test the limits of their mental and physical strength.", uiMapID=246, x=0.33333298564, y=0.62090200186, rootSection=5497,
      creatures = { {display=16628, file=607624, name="Grand Warlock Nethekurse"} },
