          body="Warbringer O'mrogg inflicts $30633s1 Nature damage to nearby players, reducing their attack speed by $30633s3% and slowing their movement by $30633s2% for $30633d." },
        { id=5894, title="Beatdown", parent=0, child=0, sib=5895, order=2, spell=0, icon=132345, flags=1, cdisp=0,
          body="Warbringer O'mrogg chooses a random player and beats them down, clearing all threat and giving a large amount of threat to his Beatdown target." },
        { id=5895, title="Fear", parent=0, child=0, sib=5896, order=3, spell=0, icon=136183, flags=128, cdisp=0,
