        { id=5896, title="Burning Maul", parent=0, child=0, sib=5897, order=4, spell=0, icon=135814, flags=36, cdisp=0,
          body="Warbringer O'mrogg ignites his maul, inflicting $36057s1 additional Fire damage to all players near his target with each melee attack for $36056d." },
        { id=5897, title="Blast Wave", parent=0, child=0, sib=0, order=5, spell=0, icon=135903, flags=64, cdisp=0,
          body="Warbringer O'mrogg unleashes a wave of flame, inflicting $30600s1 Fire damage to nearby players and reducing their movement speed by $30600s2% for $30600d." },
      },
