add{ id=261, name="The Steamvault", isRaid=false, minLevel=69, mapID=545, loreFDID=608238, bgFDID=608160, buttonFDID=608199, desc="Coilfang Reservoir is the name for a naga-dominated compound that lurks under Zangarmarsh's deepest waters. The reservoir, punctured throughout by massive open pipes and pistons, seems big enough to house armies - and, yet, its purpose isn't strictly military.",
  encounters = {
    { id=573, name="Hydromancer Thespia", order=1, desc="At the height of the night elf empire, the Highborne Thespia delighted in art and music. Her love of these things vanished during the Great Sundering, when she and many of her kin were sucked into Azeroth's deeps and transformed into hateful naga. In the millennia that followed, Thespia remained a close confidant of her childhood friend, Lady Vashj. Without hesitation, she journeyed with her comrade to Zangarmarsh and vowed to oversee the naga's quest to drain the region's water supply.", uiMapID=263, x=0.54234999418, y=0.1372949928, rootSection=5982,
      creatures = { {display=11268, file=607651, name="Hydromancer Thespia"} },
      loot = {
        {id=29434,pct=100.0,diff="h"}, {id=30828,pct=100.0}, {id=27508,pct=20.0}, {id=27783,pct=20.0}, {id=27784,pct=20.0}, {id=27787,pct=20.0}, {id=27789,pct=20.0}, {id=29673,pct=5.0}, {id=30549,pct=5.0,diff="h"}, {id=30550,pct=5.0,diff="h"},
