add{ id=751, name="Black Temple", isRaid=true, minLevel=70, mapID=564, loreFDID=1396498, bgFDID=1396453, buttonFDID=1396579,
  encounters = {
    { id=1582, name="High Warlord Naj'entus", order=0, uiMapID=340, x=0.43948701024, y=0.18765099347, rootSection=15578,
      creatures = { {display=21174, file=1378986, name="High Warlord Naj'entus"} },
      loot = {
        {id=32232,pct=14.3}, {id=32234,pct=14.3}, {id=32236,pct=14.3}, {id=32237,pct=14.3}, {id=32238,pct=14.3}, {id=32239,pct=14.3}, {id=32240,pct=14.3}, {id=32241,pct=14.3}, {id=32242,pct=14.3}, {id=32243,pct=14.3},
        {id=32245,pct=14.3}, {id=32247,pct=14.3}, {id=32248,pct=14.3}, {id=32377,pct=14.3},
      },
      sections = {
        { id=15578, title="Overview", parent=0, child=15579, sib=15587, order=1, spell=0, icon=0, flags=0, cdisp=0,
          body="High Warlord Naj'entus periodically skewers players with his Impaling Spines, stunning them until freed by allies. Over the course of the encounter, Naj'entus casts Tidal Shield, becoming immune to damage and restoring health over time until a player hurls a Spine back at him to pierce the bubble." },
        { id=15587, title="Section 10", parent=0, child=0, sib=15585, order=5, spell=39837, icon=0, flags=32, cdisp=0,
          body="" },
        { id=15585, title="Section 8", parent=0, child=15586, sib=15584, order=6, spell=39872, icon=0, flags=32, cdisp=0,
          body="" },
        { id=15584, title="Section 7", parent=0, child=0, sib=15583, order=8, spell=39835, icon=0, flags=0, cdisp=0,
          body="" },
        { id=15583, title="Section 5", parent=0, child=0, sib=15582, order=9, spell=39836, icon=132152, flags=1, cdisp=0,
          body="" },
        { id=15582, title="Section 6", parent=0, child=0, sib=0, order=10, spell=19818, icon=0, flags=1, cdisp=0,
          body="" },
        { id=15579, title="Damage Dealers", parent=15578, child=0, sib=15580, order=2, spell=0, icon=0, flags=2, cdisp=0,
          body="$bullet;Spread out to reduce damage taken from |cFF2959D3|Hspell:39835|h[Needle Spine]|h|r.\n$bullet;Interact with Naj'entus' Spine to free a player stunned by |cFF2959D3|Hspell:39837|h[Impaling Spine]|h|r.\n$bullet;Throw Naj'entus' Spine at High Warlord Naj'entus to cancel |cFF2959D3|Hspell:39872|h[Tidal Shield]|h|r." },
        { id=15580, title="Healers", parent=15578, child=0, sib=15581, order=3, spell=0, icon=0, flags=4, cdisp=0,
          body="$bullet;Spread out to reduce damage taken from |cFF2959D3|Hspell:39835|h[Needle Spine]|h|r.\n$bullet;Interact with Naj'entus' Spine to free a player stunned by |cFF2959D3|Hspell:39837|h[Impaling Spine]|h|r.\n$bullet;Throw Naj'entus' Spine at High Warlord Naj'entus to cancel |cFF2959D3|Hspell:39872|h[Tidal Shield]|h|r." },
        { id=15581, title="Tanks", parent=15578, child=0, sib=0, order=4, spell=0, icon=0, flags=1, cdisp=0,
          body="$bullet;Avoid facing High Warlord Naj'entus at allies to avoid damage from |cFF2959D3|Hspell:39836|h[Horseshoe Swipe]|h|r.\n$bullet;Interact with Naj'entus' Spine to free a player stunned by |cFF2959D3|Hspell:39837|h[Impaling Spine]|h|r.\n$bullet;Throw Naj'entus' Spine at High Warlord Naj'entus to cancel |cFF2959D3|Hspell:39872|h[Tidal Shield]|h|r." },
        { id=15586, title="Section 9", parent=15585, child=0, sib=0, order=7, spell=39878, icon=0, flags=16, cdisp=0,
          body="" },
      },
    },
