      },
      sections = {
        { id=15645, title="Overview", parent=0, child=15646, sib=15649, order=1, spell=0, icon=0, flags=0, cdisp=0,
          body="As the fight progresses, the Gurtogg swaps between two modes that determine which abilities he uses. In one mode, he afflicts distant targets with deadly maladies, while in the other he fixates on a random player with his full might." },
        { id=15649, title="Stage One: Boiling Blood", parent=0, child=15650, sib=15654, order=5, spell=0, icon=0, flags=0, cdisp=0,
          body="" },
        { id=15654, title="Stage Two: Fel Rage", parent=0, child=15657, sib=0, order=10, spell=0, icon=0, flags=0, cdisp=0,
          body="" },
        { id=15646, title="Damage Dealers", parent=15645, child=0, sib=15647, order=2, spell=0, icon=0, flags=2, cdisp=0,
          body="$bullet;Coordinate your positioning with group members to avoid getting too many stacks of |cFF2959D3|Hspell:42005|h[Blood Boil]|h|r." },
        { id=15647, title="Healers", parent=15645, child=0, sib=15648, order=3, spell=0, icon=0, flags=4, cdisp=0,
          body="$bullet;Coordinate your positioning with group members to avoid getting too many stacks of |cFF2959D3|Hspell:42005|h[Blood Boil]|h|r.\n$bullet;Heal the ally that is targeted with |cFF2959D3|Hspell:40604|h[Fel Rage]|h|r." },
        { id=15648, title="Tanks", parent=15645, child=0, sib=0, order=4, spell=0, icon=0, flags=1, cdisp=0,
          body="$bullet;Take turns tanking Gurtogg to keep the application of |cFF2959D3|Hspell:40484|h[Acidic Wound]|h|r in check." },
