    { id=1587, name="Reliquary of Souls", order=5, uiMapID=342, x=0.61384397745, y=0.85076802969, rootSection=15661,
      creatures = { {display=21483, file=1385764, name="Reliquary of Souls"} },
      loot = {
        {id=32345,pct=16.7}, {id=32346,pct=16.7}, {id=32347,pct=16.7}, {id=32349,pct=16.7}, {id=32350,pct=16.7}, {id=32362,pct=16.7}, {id=32332,pct=14.3}, {id=32351,pct=14.3}, {id=32352,pct=14.3}, {id=32353,pct=14.3},
        {id=32354,pct=14.3}, {id=32363,pct=14.3}, {id=32517,pct=14.3},
      },
      sections = {
        { id=15661, title="Overview", parent=0, child=15662, sib=15665, order=1, spell=0, icon=0, flags=0, cdisp=0,
          body="The Reliquary of Souls manifests three different Essences over the course of the encounter, each of which applies unique effects that must be handled differently. \n\nFirst, the Essence of Suffering always strikes the nearest player and afflicts the raid with |cFF2959D3|Hspell:41292|h[Aura of Suffering]|h|r.\n\nSecond, the Essence of Desire afflicts the raid with |cFF2959D3|Hspell:41350|h[Aura of Desire]|h|r.\n\nFinally, players must defeat the Essence of Anger which afflicts the raid with |cFF2959D3|Hspell:41337|h[Aura of Anger]|h|r." },
        { id=15665, title="Stage One: Essence of Suffering", parent=0, child=15666, sib=15670, order=5, spell=0, icon=0, flags=0, cdisp=0,
          body="" },
        { id=15670, title="Intermission: Release Enslaved Souls", parent=0, child=15671, sib=15673, order=10, spell=0, icon=0, flags=0, cdisp=0,
          body="" },
        { id=15673, title="Stage Two: Essence of Desire", parent=0, child=15674, sib=15678, order=13, spell=0, icon=0, flags=0, cdisp=0,
          body="" },
        { id=15678, title="Intermission: Release Enslaved Souls", parent=0, child=15679, sib=15681, order=18, spell=0, icon=0, flags=0, cdisp=0,
          body="" },
        { id=15681, title="Stage Three: Essence of Anger", parent=0, child=15682, sib=0, order=21, spell=0, icon=0, flags=0, cdisp=0,
          body="" },
        { id=15662, title="Damage Dealers", parent=15661, child=0, sib=15663, order=2, spell=0, icon=0, flags=2, cdisp=0,
          body="$bullet;Avoid heavily damaging yourself during |cFF2959D3|Hspell:41350|h[Aura of Desire]|h|r.\n$bullet;Be aware of your threat while|cFF2959D3|Hspell:41520|h[Seethe]|h|r is active." },
        { id=15663, title="Healers", parent=15661, child=0, sib=15664, order=3, spell=0, icon=0, flags=4, cdisp=0,
          body="$bullet;Watch your mana during |cFF2959D3|Hspell:41292|h[Aura of Suffering]|h|r.\n$bullet;Quickly dispel |cFF2959D3|Hspell:41303|h[Soul Drain]|h|r.\n$bullet;Regenerate Mana from the Enslaved Souls during the Intermission stage." },
        { id=15664, title="Tanks", parent=15661, child=0, sib=0, order=4, spell=0, icon=0, flags=1, cdisp=0,
          body="$bullet;While the Essence of Desire is active, be careful of |cFF2959D3|Hspell:41410|h[Deaden]|h|r.\n$bullet;Using a Taunt effect while the Essence of Anger is active will cause |cFF2959D3|Hspell:41364|h[Seethe]|h|r.\n$bullet;Face the Essence of Anger away from allies to avoid damage from |cFF2959D3|Hspell:41545|h[Soul Scream]|h|r." },
        { id=15666, title="Section 6", parent=15665, child=0, sib=15667, order=6, spell=41292, icon=0, flags=32, cdisp=0,
          body="" },
        { id=15667, title="Section 7", parent=15665, child=0, sib=15668, order=7, spell=41294, icon=0, flags=0, cdisp=0,
