      creatures = { {display=21416, file=1385743, name="The Illidari Council"} },
      loot = {
        {id=31098,pct=33.3}, {id=31099,pct=33.3}, {id=31100,pct=33.3}, {id=32331,pct=16.7}, {id=32373,pct=16.7}, {id=32376,pct=16.7}, {id=32505,pct=16.7}, {id=32518,pct=16.7}, {id=32519,pct=16.7},
      },
      sections = {
        { id=15700, title="Overview", parent=0, child=15701, sib=15704, order=1, spell=0, icon=0, flags=0, cdisp=0,
          body="The Illidari Council consists of a powerful paladin, rogue, mage, and priest. They share health and bring their iconic abilities to bear against their foes." },
        { id=15704, title="Gathios the Shatterer", parent=0, child=15705, sib=15716, order=5, spell=0, icon=0, flags=0, cdisp=21416,
          body="" },
        { id=15716, title="Veras Darkshadow", parent=0, child=15717, sib=15720, order=15, spell=0, icon=0, flags=0, cdisp=21418,
          body="" },
        { id=15720, title="High Nethermancer Zerevor", parent=0, child=15721, sib=15726, order=19, spell=0, icon=0, flags=0, cdisp=21417,
          body="" },
        { id=15726, title="Lady Malande", parent=0, child=15727, sib=0, order=25, spell=0, icon=0, flags=0, cdisp=21419,
          body="" },
        { id=15701, title="Damage Dealers", parent=15700, child=0, sib=15702, order=2, spell=0, icon=0, flags=2, cdisp=0,
          body="$bullet;Melee damage dealers should avoid striking High Nethermancer Zerevor due to his |cFF2959D3|Hspell:41524|h[Arcane Explosion]|h|r.\n$bullet;Interrupt Lady Malande's |cFF2959D3|Hspell:41455|h[Circle of Healing]|h|r." },
        { id=15702, title="Healers", parent=15700, child=0, sib=15703, order=3, spell=0, icon=0, flags=4, cdisp=0,
          body="$bullet;Allies afflicted with Veras's |cFF2959D3|Hspell:41487|h[Envenom]|h|r require urgent healing attention." },
        { id=15703, title="Tanks", parent=15700, child=0, sib=0, order=4, spell=0, icon=0, flags=1, cdisp=0,
          body="$bullet;Hold the attention of Gathios the Shatterer and Veras Darkshadow.\n$bullet;Keep Gathios the Shatterer away from the other members of the council to avoid buffing them with |cFF2959D3|Hspell:41452|h[Devotion Aura]|h|r." },
        { id=15705, title="Blessings", parent=15704, child=15706, sib=15711, order=6, spell=0, icon=135908, flags=0, cdisp=0,
          body="Gathios can have one Blessing active at a time." },
        { id=15711, title="Judgments", parent=15704, child=15712, sib=15710, order=9, spell=0, icon=236258, flags=0, cdisp=0,
          body="Gathios will cast a Judgement based on which Seal he has active." },
