    { id=1590, name="Illidan Stormrage", order=8, uiMapID=346, x=0.52769100666, y=0.70461297035, rootSection=15731,
      creatures = { {display=21135, file=1378987, name="Illidan Stormrage"} },
      loot = {
        {id=31089,pct=33.3}, {id=31090,pct=33.3}, {id=31091,pct=33.3}, {id=32235,pct=16.7}, {id=32336,pct=16.7}, {id=32374,pct=16.7}, {id=32375,pct=16.7}, {id=32471,pct=16.7}, {id=32483,pct=16.7}, {id=32496,pct=16.7},
        {id=32497,pct=16.7}, {id=32500,pct=16.7}, {id=32521,pct=16.7}, {id=32524,pct=16.7}, {id=32525,pct=16.7}, {id=32837,pct=4.0}, {id=32838,pct=4.0},
      },
      sections = {
        { id=15731, title="Overview", parent=0, child=15732, sib=15735, order=1, spell=0, icon=0, flags=0, cdisp=0,
          body="Illidan wields his Warglaives at the start of the encounter, infecting foes with |cFF2959D3|Hspell:41917|h[Parasitic Shadowfiend]|h|r.\n\nUpon reaching 65% health, Illidan takes flight and throws the Warglaives of Azzinoth to the ground, each of which unleashes a Flame. The two Flames of Azzinoth must be defeated to bring Illidan to the ground.\n\nFor the remainder of the encounter, Illidan periodically unleashes the power of the demonic force within him, using those dark powers to assault his foes, before returning to his natural form.\n\nAt 30% health, Maiev arrives to assist in handling the Betrayer's final efforts to overpower his foes." },
        { id=15735, title="Stage One: You Are Not Prepared", parent=0, child=15746, sib=15740, order=5, spell=0, icon=0, flags=0, cdisp=0,
          body="" },
        { id=15740, title="Stage Two: Flames of Azzinoth", parent=0, child=15758, sib=15751, order=10, spell=0, icon=0, flags=0, cdisp=0,
          body="" },
        { id=15751, title="Stage Three: The Demon Within", parent=0, child=15764, sib=15757, order=18, spell=0, icon=0, flags=0, cdisp=0,
          body="" },
        { id=15757, title="Stage Four: The Long Hunt", parent=0, child=15762, sib=0, order=29, spell=0, icon=0, flags=0, cdisp=0,
          body="" },
        { id=15732, title="Damage Dealers", parent=15731, child=0, sib=15733, order=2, spell=0, icon=0, flags=2, cdisp=0,
          body="$bullet;Move away from allies when afflicted with |cFF2959D3|Hspell:41917|h[Parasitic Shadowfiend]|h|r.\n$bullet;Quickly defeat the Flames of Azzinoth in Stage Two of the encounter." },
        { id=15733, title="Healers", parent=15731, child=0, sib=15734, order=3, spell=0, icon=0, flags=4, cdisp=0,
          body="$bullet;Move away from allies when afflicted with |cFF2959D3|Hspell:41917|h[Parasitic Shadowfiend]|h|r.\n$bullet;Quickly defeat the Flames of Azzinoth in Stage Two of the encounter." },
        { id=15734, title="Tanks", parent=15731, child=0, sib=0, order=4, spell=0, icon=0, flags=1, cdisp=0,
