-- Per-expansion instance-select background: UI-EJ-BurningCrusade standalone BLP
-- (ManifestInterfaceData 605326), sibling of the shipped Classic 605327. The tier dropdown
-- in EncounterJournal.lua swaps the instance-select bg to this on the "Burning Crusade" radio.
--
-- The remaining loops register the per-instance art the renderer references: grid/back-button
-- splashes (JournalInstance.ButtonFileDataID), model-tab backdrops (BackgroundFileDataID),
-- lore-panel splashes (LoreFileDataID), and boss-list portraits (JournalEncounterCreature
-- .FileDataID). These Cata-era FDIDs are absent from the TBC client CASC, so without these
-- local BLPs every TBC instance rendered file=0; extracted by tools/gen_ej_blps.py. All
-- TBC-only (Era's Data.lua references none of them -> the Era zip excludes them).
if NE.tex and NE.tex.RegisterLocal then
  local _P = "Interface\\AddOns\\DragonUI_NewEra\\Textures\\EncounterJournal\\"
  local function reg(fd, path)
    NE.tex.RegisterLocal(fd, path)
    if NE.ej.Preload then NE.ej.Preload(path) end
  end
  reg(605326, _P .. "605326-ui-ej-burningcrusade.blp")
  -- instance-select button splashes (root, <FDID>-ejbutton-<nick>.blp)
  reg(608193, _P .. "608193-ejbutton-auchindoun.blp")
  reg(608198, _P .. "608198-ejbutton-caverns-of-time.blp")
  reg(608199, _P .. "608199-ejbutton-coilfang.blp")
  reg(608207, _P .. "608207-ejbutton-hellfire-citadel.blp")
  reg(608208, _P .. "608208-ejbutton-magisters-terrace.blp")
  reg(608218, _P .. "608218-ejbutton-tempest-keep.blp")
  reg(1396579, _P .. "1396579-ejbutton-black-temple.blp")
  reg(1396582, _P .. "1396582-ejbutton-gruuls-lair.blp")
  reg(1396584, _P .. "1396584-ejbutton-karazhan.blp")
  reg(1396585, _P .. "1396585-ejbutton-magtheridons-lair.blp")
  reg(522363, _P .. "522363-ejbutton-zulaman.blp")
  reg(1396592, _P .. "1396592-ejbutton-sunwell-plateau.blp")
  -- model-tab backdrops / lore splashes / boss portraits (FDID-named, in subfolders)
  for _, fd in ipairs({ 522347, 608154, 608159, 608160, 608168, 608169, 608179, 1396453, 1396456, 1396458, 1396459, 1396466 }) do reg(fd, _P .. "Backdrops\\" .. fd .. ".blp") end
  for _, fd in ipairs({ 526415, 608232, 608237, 608238, 608246, 608247, 608257, 1396498, 1396501, 1396503, 1396504, 1396511 }) do reg(fd, _P .. "Lore\\" .. fd .. ".blp") end
  for _, fd in ipairs({
    607529, 607536, 607544, 607555, 607556, 607558, 607561, 607566, 607570, 607574, 607583, 607596,
    607600, 607614, 607624, 607625, 607635, 607641, 607649, 607651, 607669, 607670, 607683, 607689,
    607712, 607713, 607715, 607720, 607725, 607726, 607734, 607738, 607739, 607742, 607750, 607759,
    607767, 607771, 607779, 607780, 607782, 607784, 607788, 607789, 607794, 607803, 607806, 607811,
    607812, 607815, 607816, 607817, 607820, 607822, 607823, 1378965, 1378982, 1378983, 1378985, 1378986,
    1378987, 1378996, 1378997, 1378999, 1379000, 1379002, 1379006, 1379011, 1379012, 1379016, 1379017, 1379018,
    1379020, 1385712, 1385714, 1385716, 1385719, 1385722, 1385725, 1385729, 1385730, 1385739, 1385741, 1385743,
    1385744, 1385745, 1385746, 1385750, 1385751, 1385756, 1385757, 1385758, 1385762, 1385764, 1385766, 1385768,
    1385772, 1390438, 522217, 522235, 522231, 522242, 522254, 522190, 69420,
